sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_preset;
uniform float amzp_amount;
uniform float amzp_holoOpacity;
uniform float amzp_srcColors;
uniform float amzp_holoBright;
uniform float amzp_edgeGlow;
uniform float amzp_edgeWidth;
uniform float amzp_flicker;
uniform float amzp_flickSpeed;
uniform float amzp_scan;
uniform float amzp_scanSize;
uniform float amzp_scanSpeed;
uniform float amzp_interf;
uniform float amzp_bandSpeed;
uniform float amzp_glitch;
uniform float amzp_glitchRate;
uniform float amzp_rgbSplit;
uniform float amzp_noise;
uniform float amzp_rainMix;
uniform float amzp_rainArea;
uniform float amzp_glyphStyle;
uniform float amzp_cellSize;
uniform float amzp_rainSpeed;
uniform float amzp_trail;
uniform float amzp_density;
uniform float amzp_glyphChange;
uniform float amzp_headGlow;
uniform float amzp_seed;
layout(color) uniform half4 amzp_holoColor;
layout(color) uniform half4 amzp_holoHi;
layout(color) uniform half4 amzp_rainColor;
layout(color) uniform half4 amzp_headColor;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 7.137) * 43758.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float4 at(float2 uv) { return (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) ? float4(0.0) : amzTexture(0, l2s(uv)); }
    float lum(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float3 cA, cB, cR, cH;
    float mScan, mGlitch, mRain, mFlick, mGlow, mInterf;
    void applyPreset() {
        cA = amzp_holoColor.rgb; cB = amzp_holoHi.rgb; cR = amzp_rainColor.rgb; cH = amzp_headColor.rgb;
        mScan = 1.0; mGlitch = 1.0; mRain = 1.0; mFlick = 1.0; mGlow = 1.0; mInterf = 1.0;
        if (int(amzp_preset) == 1) { cA = float3(0.0, 0.16, 0.05); cB = float3(0.45, 1.0, 0.55); cR = float3(0.1, 1.0, 0.35); cH = float3(0.85, 1.0, 0.9); }
        else if (int(amzp_preset) == 2) { cA = float3(0.02, 0.12, 0.3); cB = float3(0.45, 0.85, 1.0); cR = float3(0.2, 0.6, 1.0); cH = float3(0.85, 0.95, 1.0); mRain = 0.6; }
        else if (int(amzp_preset) == 3) { cA = float3(0.18, 0.0, 0.25); cB = float3(0.1, 0.95, 1.0); cR = float3(1.0, 0.15, 0.75); cH = float3(1.0, 0.85, 1.0); mGlitch = 1.4; }
        else if (int(amzp_preset) == 4) { cA = float3(0.25, 0.0, 0.0); cB = float3(1.0, 0.35, 0.25); cR = float3(1.0, 0.1, 0.05); cH = float3(1.0, 0.85, 0.75); mFlick = 1.8; mGlitch = 1.3; }
        else if (int(amzp_preset) == 5) { cA = float3(0.2, 0.1, 0.0); cB = float3(1.0, 0.85, 0.4); cR = float3(1.0, 0.7, 0.15); cH = float3(1.0, 0.97, 0.8); }
        else if (int(amzp_preset) == 6) { cA = float3(0.12, 0.14, 0.18); cB = float3(0.95, 0.97, 1.0); cR = float3(0.8, 0.85, 0.95); cH = float3(1.0); mRain = 0.5; mFlick = 1.5; }
        else if (int(amzp_preset) == 7) { cA = float3(0.05, 0.2, 0.0); cB = float3(0.8, 1.0, 0.2); cR = float3(0.6, 1.0, 0.0); cH = float3(1.0, 1.0, 0.6); }
        else if (int(amzp_preset) == 8) { cA = float3(0.12, 0.02, 0.25); cB = float3(0.8, 0.5, 1.0); cR = float3(0.65, 0.3, 1.0); cH = float3(0.95, 0.85, 1.0); }
        else if (int(amzp_preset) == 9) { cA = float3(0.05, 0.2, 0.28); cB = float3(0.75, 1.0, 1.0); cR = float3(0.4, 0.95, 1.0); cH = float3(1.0); mGlitch = 0.6; }
        else if (int(amzp_preset) == 10) { cA = float3(0.3, 0.05, 0.15); cB = float3(1.0, 0.65, 0.35); cR = float3(1.0, 0.35, 0.55); cH = float3(1.0, 0.92, 0.7); }
        else if (int(amzp_preset) == 11) { cA = float3(0.0, 0.1, 0.18); cB = float3(0.2, 0.9, 0.85); cR = float3(0.0, 0.7, 0.8); cH = float3(0.7, 1.0, 1.0); mInterf = 1.5; }
        else if (int(amzp_preset) == 12) { cA = float3(0.15, 0.06, 0.0); cB = float3(1.0, 0.7, 0.2); cR = float3(1.0, 0.6, 0.1); cH = float3(1.0, 0.9, 0.6); mScan = 1.6; }
        else if (int(amzp_preset) == 13) { cA = float3(0.0, 0.18, 0.12); cB = float3(0.3, 1.0, 0.75); cR = float3(0.0, 1.0, 0.66); cH = float3(0.8, 1.0, 0.95); mGlow = 1.4; }
        else if (int(amzp_preset) == 14) { cA = float3(0.1, 0.0, 0.2); cB = float3(0.4, 1.0, 0.9); cR = float3(0.2, 1.0, 0.4); cH = float3(1.0); mGlitch = 3.0; mFlick = 2.0; mScan = 1.3; }
        else if (int(amzp_preset) == 15) { cA = float3(0.03, 0.14, 0.26); cB = float3(0.55, 0.9, 1.0); cR = float3(0.3, 0.7, 1.0); cH = float3(0.9, 0.97, 1.0); mRain = 0.0; mGlitch = 0.3; mFlick = 0.4; mInterf = 1.3; }
    }
    float glyph(float2 g, float2 id) {
        if (g.x < 0.0 || g.y < 0.0 || g.x > 1.0 || g.y > 1.0) return 0.0;
        if (int(amzp_glyphStyle) == 1) {
            if (h2(id + 4.7) < 0.5) {
                float2 q = (g - 0.5) / float2(0.32, 0.42);
                float r = length(q);
                return smoothstep(0.32, 0.2, abs(r - 0.8));
            }
            float bar = step(abs(g.x - 0.52), 0.1) * step(0.08, g.y) * step(g.y, 0.92);
            float flag = step(abs(g.y - 0.8 + (g.x - 0.4) * 0.6), 0.07) * step(0.25, g.x) * step(g.x, 0.52);
            return max(bar, flag);
        }
        if (int(amzp_glyphStyle) == 2) {
            float2 b = floor(g * 2.0);
            return step(0.35, h2(id + b * 3.1)) * step(abs(fract(g.x * 2.0) - 0.5), 0.42) * step(abs(fract(g.y * 2.0) - 0.5), 0.42);
        }
        if (int(amzp_glyphStyle) == 3) return smoothstep(0.36, 0.26, length(g - 0.5));
        float2 gi = floor(g * float2(5.0, 7.0));
        float2 sub = fract(g * float2(5.0, 7.0));
        float gx = h2(id + 9.1) < 0.6 ? min(gi.x, 4.0 - gi.x) : gi.x;
        float on = step(0.52, h2(id * 1.7 + float2(gx * 13.0, gi.y * 7.0)));
        float2 dq = abs(sub - 0.5);
        return on * step(max(dq.x, dq.y), 0.44);
    }
    void nmMain() {
        applyPreset();
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float t = time;
        float4 orig = at(uv);
        float gk = clamp(amzp_glitch * mGlitch, 0.0, 6.0);
        float gt = floor(t * amzp_glitchRate);
        float band = floor(uv.y * 26.0 + h1(gt) * 9.0);
        float gOn = step(1.0 - min(gk * 0.25, 0.9), h2(float2(band, gt))) * step(0.001, gk);
        float2 guv = uv + float2(gOn * (h2(float2(band + 3.1, gt)) - 0.5) * 0.1 * gk, 0.0);
        float sh = amzp_rgbSplit * (1.0 + gOn * 3.0) / max(W.x, 1.0);
        float4 sc = at(guv);
        float4 sr = at(guv + float2(sh, 0.0));
        float4 sb = at(guv - float2(sh, 0.0));
        float a = max(sc.a, max(sr.a, sb.a));
        float3 cc = unp(sc);
        float3 hc = mix(cA, cB, smoothstep(0.0, 1.0, lum(cc)));
        hc = mix(hc, cc, clamp(amzp_srcColors, 0.0, 1.0));
        float3 hr = mix(mix(cA, cB, smoothstep(0.0, 1.0, lum(unp(sr)))), unp(sr), clamp(amzp_srcColors, 0.0, 1.0));
        float3 hb = mix(mix(cA, cB, smoothstep(0.0, 1.0, lum(unp(sb)))), unp(sb), clamp(amzp_srcColors, 0.0, 1.0));
        float3 col = float3(sr.a > 0.0001 ? hr.r : hc.r, hc.g, sb.a > 0.0001 ? hb.b : hc.b) * amzp_holoBright;
        float2 e = float2(amzp_edgeWidth) / max(W, float2(1.0));
        float mn = min(min(at(guv + float2(e.x, 0.0)).a, at(guv - float2(e.x, 0.0)).a), min(at(guv + float2(0.0, e.y)).a, at(guv - float2(0.0, e.y)).a));
        float mx = max(max(at(guv + float2(e.x, 0.0)).a, at(guv - float2(e.x, 0.0)).a), max(at(guv + float2(0.0, e.y)).a, at(guv - float2(0.0, e.y)).a));
        float rim = clamp(a * (1.0 - mn) + mx * (1.0 - a) * 0.5, 0.0, 1.0) * amzp_edgeGlow * mGlow;
        float py = (1.0 - uv.y) * W.y;
        float s = 0.5 + 0.5 * sin(6.2831853 * (py / max(amzp_scanSize, 1.0) - t * amzp_scanSpeed));
        float scanK = 1.0 - clamp(amzp_scan * mScan, 0.0, 1.0) * (1.0 - s) * 0.85;
        float bnd = smoothstep(0.82, 1.0, 0.5 + 0.5 * sin(6.2831853 * (uv.y * 2.5 + t * amzp_bandSpeed)));
        bnd += 0.5 * smoothstep(0.9, 1.0, 0.5 + 0.5 * sin(6.2831853 * (uv.y * 7.0 - t * amzp_bandSpeed * 1.7 + 0.3)));
        float fl = 1.0 - clamp(amzp_flicker * mFlick, 0.0, 1.0) * 0.6 * step(0.55, h1(floor(t * amzp_flickSpeed) + 2.0)) * h1(floor(t * amzp_flickSpeed) + 5.0);
        float gr = (h2(uv * W + fract(t * 7.13) * 100.0) - 0.5) * amzp_noise;
        float3 holo = (col * scanK + cB * bnd * amzp_interf * mInterf * 0.5 + gr) * fl + cB * rim;
        float ha = clamp(a * amzp_holoOpacity * (0.75 + 0.25 * scanK) * fl + rim * 0.6, 0.0, 1.0);
        float3 hp = clamp(holo, 0.0, 1.0) * ha;
        float3 rain = float3(0.0);
        float rk = amzp_rainMix * mRain;
        if (rk > 0.0) {
            float cs = max(amzp_cellSize, 3.0);
            float2 pc = float2(uv.x * W.x, py);
            float2 cell = floor(pc / cs);
            float2 f = fract(pc / cs);
            float rows = W.y / cs;
            float it = 0.0, hd = 0.0;
            for (int k = 0; k < 2; k++) {
                float cx = cell.x + float(k) * 1013.0;
                if (h1(cx + 7.3) > amzp_density) continue;
                float sp = mix(0.5, 1.5, h1(cx + 1.1)) * amzp_rainSpeed;
                float L = mix(4.0, 32.0, clamp(amzp_trail, 0.0, 1.0)) * (0.6 + 0.8 * h1(cx + 3.1));
                float hp0 = fract(t * sp * 0.18 + h1(cx + 1.7)) * (rows + L);
                float d = hp0 - cell.y;
                if (d < 0.0 || d > L) continue;
                it = max(it, pow(1.0 - d / L, 1.6));
                hd = max(hd, 1.0 - smoothstep(0.0, 1.0, d));
            }
            if (it > 0.0) {
                float2 gid = cell + floor(t * amzp_glyphChange * (0.4 + h2(cell + 2.2))) * float2(17.0, 31.0);
                float g = glyph((f - float2(0.14, 0.08)) / float2(0.72, 0.84), gid);
                float area = int(amzp_rainArea) == 0 ? orig.a : (int(amzp_rainArea) == 1 ? 1.0 : 1.0 - orig.a);
                float3 rc = mix(cR, cH, hd * clamp(amzp_headGlow, 0.0, 1.0)) * (1.0 + hd * max(amzp_headGlow - 1.0, 0.0));
                rain = rc * g * it * rk * area;
            }
        }
        float ra = clamp(max(rain.r, max(rain.g, rain.b)), 0.0, 1.0);
        float oa = clamp(ha + ra * (1.0 - ha), 0.0, 1.0);
        float3 orgb = min(hp + rain, float3(oa));
        amzOutput = mix(orig, float4(orgb, oa), clamp(amzp_amount, 0.0, 1.0));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
